pub fn contains(property: Property, codepoint: u21) bool {
    return switch (property) {
        .ascii => inRanges(&ranges_ascii, codepoint),
        .any => inRanges(&ranges_any, codepoint),
        .ascii_hex_digit => inRanges(&ranges_ascii_hex_digit, codepoint),
        .assigned => inRanges(&ranges_assigned, codepoint),
        .alphabetic => inRanges(&ranges_alphabetic, codepoint),
        .bidi_control => inRanges(&ranges_bidi_control, codepoint),
        .bidi_mirrored => inRanges(&ranges_bidi_mirrored, codepoint),
        .case_ignorable => inRanges(&ranges_case_ignorable, codepoint),
        .cased => inRanges(&ranges_cased, codepoint),
        .changes_when_casefolded => inRanges(&ranges_changes_when_casefolded, codepoint),
        .changes_when_casemapped => inRanges(&ranges_changes_when_casemapped, codepoint),
        .changes_when_lowercased => inRanges(&ranges_changes_when_lowercased, codepoint),
        .changes_when_nfkc_casefolded => inRanges(&ranges_changes_when_nfkc_casefolded, codepoint),
        .changes_when_titlecased => inRanges(&ranges_changes_when_titlecased, codepoint),
        .changes_when_uppercased => inRanges(&ranges_changes_when_uppercased, codepoint),
        .dash => inRanges(&ranges_dash, codepoint),
        .default_ignorable_code_point => inRanges(&ranges_default_ignorable_code_point, codepoint),
        .deprecated => inRanges(&ranges_deprecated, codepoint),
        .diacritic => inRanges(&ranges_diacritic, codepoint),
        .emoji_component => inRanges(&ranges_emoji_component, codepoint),
        .emoji_modifier => inRanges(&ranges_emoji_modifier, codepoint),
        .emoji_modifier_base => inRanges(&ranges_emoji_modifier_base, codepoint),
        .extender => inRanges(&ranges_extender, codepoint),
        .grapheme_base => inRanges(&ranges_grapheme_base, codepoint),
        .grapheme_extend => inRanges(&ranges_grapheme_extend, codepoint),
        .hex_digit => inRanges(&ranges_hex_digit, codepoint),
        .ideographic => inRanges(&ranges_ideographic, codepoint),
        .ids_binary_operator => inRanges(&ranges_ids_binary_operator, codepoint),
        .ids_trinary_operator => inRanges(&ranges_ids_trinary_operator, codepoint),
        .join_control => inRanges(&ranges_join_control, codepoint),
        .logical_order_exception => inRanges(&ranges_logical_order_exception, codepoint),
        .lowercase => inRanges(&ranges_lowercase, codepoint),
        .math => inRanges(&ranges_math, codepoint),
        .noncharacter_code_point => inRanges(&ranges_noncharacter_code_point, codepoint),
        .pattern_syntax => inRanges(&ranges_pattern_syntax, codepoint),
        .pattern_white_space => inRanges(&ranges_pattern_white_space, codepoint),
        .quotation_mark => inRanges(&ranges_quotation_mark, codepoint),
        .radical => inRanges(&ranges_radical, codepoint),
        .regional_indicator => inRanges(&ranges_regional_indicator, codepoint),
        .sentence_terminal => inRanges(&ranges_sentence_terminal, codepoint),
        .soft_dotted => inRanges(&ranges_soft_dotted, codepoint),
        .terminal_punctuation => inRanges(&ranges_terminal_punctuation, codepoint),
        .unified_ideograph => inRanges(&ranges_unified_ideograph, codepoint),
        .uppercase => inRanges(&ranges_uppercase, codepoint),
        .variation_selector => inRanges(&ranges_variation_selector, codepoint),
        .xid_continue => inRanges(&ranges_xid_continue, codepoint),
        .xid_start => inRanges(&ranges_xid_start, codepoint),
        .cased_letter => inRanges(&ranges_cased_letter, codepoint),
        .close_punctuation => inRanges(&ranges_close_punctuation, codepoint),
        .connector_punctuation => inRanges(&ranges_connector_punctuation, codepoint),
        .control => inRanges(&ranges_control, codepoint),
        .currency_symbol => inRanges(&ranges_currency_symbol, codepoint),
        .dash_punctuation => inRanges(&ranges_dash_punctuation, codepoint),
        .enclosing_mark => inRanges(&ranges_enclosing_mark, codepoint),
        .final_punctuation => inRanges(&ranges_final_punctuation, codepoint),
        .format => inRanges(&ranges_format, codepoint),
        .initial_punctuation => inRanges(&ranges_initial_punctuation, codepoint),
        .letter_number => inRanges(&ranges_letter_number, codepoint),
        .line_separator => inRanges(&ranges_line_separator, codepoint),
        .math_symbol => inRanges(&ranges_math_symbol, codepoint),
        .modifier_letter => inRanges(&ranges_modifier_letter, codepoint),
        .modifier_symbol => inRanges(&ranges_modifier_symbol, codepoint),
        .nonspacing_mark => inRanges(&ranges_nonspacing_mark, codepoint),
        .open_punctuation => inRanges(&ranges_open_punctuation, codepoint),
        .other => inRanges(&ranges_other, codepoint),
        .other_letter => inRanges(&ranges_other_letter, codepoint),
        .other_number => inRanges(&ranges_other_number, codepoint),
